import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t,o,c as _,a3 as e}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/58-西域第四十六.md","filePath":"books/yan-tie-lun/58-西域第四十六.md","lastUpdated":1794316978000}'),i={name:"books/yan-tie-lun/58-西域第四十六.md"};function n(r,a,s,l,c,d){return o(),_("div",null,[...a[0]||(a[0]=[e('<p>西域第四十六 【题解】</p><p>本篇讨论汉家的西域政策。汉家为了取得征讨匈奴的胜利，采取了一系列经营西域的举措，如屯田、设置边郡等等，这些举措在经济上有效地充实了汉家的国库，使边疆出现“马牛放纵，蓄积布野”的局面，在军事上等于斩断匈奴的右臂，切断了匈奴与西域其他国家的联系。但是汉武帝在经营西域过程中也掺杂了个人的侈心，如不惜动用重兵去获取大宛的汗血马。大夫充分肯定汉家的西域政策，希望汉家在西域乘胜追击，彻底臣服匈奴。文学则认为匈奴地理条件特殊，根本不可能彻底臣服匈奴，并以汉家伐大宛为例，说明万里伐宛，实在是失策之举。文学进一步指出，征伐四夷已经激化了社会矛盾，导致山东农民起义反叛，因此再也不能继续征伐四夷。</p><p>大夫曰：“往者，匈奴据河、山之险[(1)]，擅田牧之利[(2)]，民富兵强，行入为寇[(3)]，则句注之内惊动[(4)]，而上郡以南咸城[(5)]。文帝时，虏入萧关[(6)]，烽火通甘泉[(7)]，群臣惧不知所出，乃请屯京师以备胡[(8)]。胡西役大宛、康居之属[(9)]，南与群羌通[(10)]。先帝推让斥夺广饶之地[(11)]，建张掖以西[(12)]，隔绝羌、胡，瓜分其援。是以西域之国，皆内拒匈奴，断其右臂，曳剑而走，故募人田畜以广用，长城以南，滨塞之郡[(13)]，马牛放纵，蓄积布野，未睹其计之所过[(14)]。夫以弱越而遂意强吴[(15)]，才地计众非钧也[(16)]，主思臣谋[(17)]，其往必矣[(18)]。”</p><p>【注释】</p><p>[(1)]河、山：黄河、阴山。</p><p>[(2)]擅：独占。田牧：田猎、放牧。</p><p>[(3)]行入：随机入侵。</p><p>[(4)]句注：关塞名，即山西代县雁门关。</p><p>[(5)]上郡：郡名，在陕西榆林东南。城：用做动词，筑城。</p><p>[(6)]萧关：关塞名，在今宁夏固原东南。</p><p>[(7)]甘泉：地名，汉代在甘泉建立离宫，在今陕西淳化甘泉山。</p><p>[(8)]屯：驻兵。《史记·匈奴列传》记载：“又置三将军军长安西细柳、渭北棘门、霸上以备胡。”</p><p>[(9)]大宛（yuān）：国名，在今乌兹别克斯坦费尔干纳盆地。康居：国名，在今哈萨克斯坦南部。</p><p>[(10)]群羌：指甘肃、青海、四川地区各支羌族。</p><p>[(11)]推让：驱逐。让，通“攘”。斥夺：“斥”意为排斥、驱逐，“夺”意为夺回，此处用做偏义复词，重点在“夺”。</p><p>[(12)]张掖：地名，位于甘肃张掖。公元前121年，霍去病进军河西，击败匈奴，汉家设置张掖郡。</p><p>[(13)]滨塞：靠近边塞。</p><p>[(14)]其计：指凿通西域、征讨匈奴。过：过错。</p><p>[(15)]遂意：满足心意。</p><p>[(16)]才地：估算土地。才，通“裁”。计众：计算人口。非钧：并非均衡。钧，通“均”。</p><p>[(17)]主思：指勾践苦思灭吴。臣谋：指范蠡、文种为之谋划。</p><p>[(18)]往：指越人出征灭吴。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“以前，匈奴占据黄河、阴山的险要位置，独占田猎、畜牧的便利，民众富足，兵马强壮，不时入侵中国边境骚扰，雁门关以内为之惊动，上郡以南地区都筑城防胡。文帝时期，匈奴入侵萧关，烽火直通陕北甘泉，朝廷群臣恐惧，不知如何是好，便请求在京师驻兵来防备匈奴。匈奴在西边役使大宛、康居这些小国，在南边与各支羌族勾通。已故武帝驱逐匈奴，夺回中国宽广富饶的土地，在张掖以西建置州郡，将羌人与匈奴隔绝开来，切断匈奴的外援。所以西域各国，都纷纷抗拒匈奴，这等于斩断了匈奴的右臂，匈奴只好拖着刀剑逃跑。汉家招募民众到河西种田放牧，以便增加国家的财用，长城以南地区，靠近边塞的郡县，民众可以随意牧马放牛，蓄积布满原野。我没有看到朝廷凿通西域、征伐匈奴的计策有什么过错。春秋时期，弱小的越国能够满足心意消灭强吴，估算土地，计算人众，吴越并非均等，越王勾践苦思灭吴，名臣范蠡、文种为之谋划，越人出征灭吴就势在必行了。”</p><p>文学曰：“吴、越迫于江、海[(1)]，三川循环之[(2)]，处于五湖之间[(3)]，地相迫，壤相次[(4)]，其势易以相禽也[(5)]。金鼓未闻[(6)]，旌旗未舒[(7)]，行军未定，兵以接矣[(8)]。师无辎重之费[(9)]，士无乏绝之劳，此所谓食于厨仓而战于门郊者也[(10)]。今匈奴牧于无穷之泽，东西南北，不可穷极，虽轻车利马，不能得也，况负重嬴兵以求之乎[(11)]？其势不相及也。茫茫乎若行九皋未知所止[(12)]，皓皓乎若无网罗而渔江、海[(13)]，虽及之[(14)]，三军罢弊[(15)]，适遗之饵也[(16)]。故明王知其无所利[(17)]，以为役不可数行[(18)]，而权不可久张也[(19)]，故诏公卿大夫、贤良、文学，所以复枉兴微之路[(20)]。公卿宜思百姓之急，匈奴之害，缘圣主之心[(21)]，定安平之业。今乃留心于末计[(22)]，摧本议[(23)]，不顺上意，未为尽于忠也。”</p><p>【注释】</p><p>[(1)]迫：蹙迫，局限。</p><p>[(2)]三川：吴江、钱塘江、浦阳江。一说，三江是松江、钱塘江和浦阳江。循环：环绕。《国语·越语上》载伍子胥说：“夫吴之与越也，仇雠敌战之国也。三江环之，民无所移，有吴则无越，有越则无吴，将不可改于是矣。”</p><p>[(3)]五湖：长荡湖、太湖、射贵湖、上湖、滆（ɡé）湖。</p><p>[(4)]次：接近。</p><p>[(5)]禽：同“擒”。</p><p>[(6)]金鼓：古代击鼓进攻，鸣金收兵。</p><p>[(7)]舒：展开。</p><p>[(8)]兵：兵器。以：通“已”。接：接触，格杀。</p><p>[(9)]辎重：军用物资，如器械、粮草等。</p><p>[(10)]厨仓：厨房。门郊：门口近郊。</p><p>[(11)]嬴兵：扛着兵器。嬴，原作“羸”，据张敦仁说校改。</p><p>[(12)]茫茫：广远的样子。九皋：九折辽阔之泽。</p><p>[(13)]皓皓：通“浩浩”，广阔辽远的样子。</p><p>[(14)]及：赶上。</p><p>[(15)]罢：同“疲”。</p><p>[(16)]适：恰好。遗：送给。之：指匈奴。饵：食物。</p><p>[(17)]无所：“无所”原作“所无”，据卢文弨说校改。</p><p>[(18)]役：战役。数行：多次进行。</p><p>[(19)]权：权威。张：扩张。</p><p>[(20)]复枉：纠正弯曲。兴微：从微小之处做起。</p><p>[(21)]缘：依据。</p><p>[(22)]末计：下策，指征伐匈奴。</p><p>[(23)]摧：原作“虽”，据张敦仁说校改。本议：根本方针，指息兵。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“吴国和越国为江河湖海所局限，松江、钱塘江和浦阳江三江环绕，处于长荡湖、太湖、射贵湖、上湖、滆湖这五湖之间，土地相连，边境接壤，这种形势使吴越容易互相冲突。军队金鼓之声未起，旌旗尚未舒展，行军部署尚未决定，双方兵器已经交接了。军队不需要军用物资费用，士卒没有精疲力竭的劳苦，这就是人们所说的在厨房吃完饭再到门外近郊去作战。如今匈奴在广阔无边的水泽草地放牧，东西南北，四方都是无边无际，即使你有轻捷的战车和飞快的战马，也不能追得上他们，何况汉兵是背着沉重的兵器去追赶他们呢？从情势来看汉兵是赶不上的。汉兵奔波在茫茫无际的水泽草原上，不知该停在哪儿，如同在浩淼无边的江海上徒手捕鱼，即使赶上匈奴，三军将士已经疲弊，恰好成为送到匈奴口边的食物。因此，当今英明的君王深知伐胡无利可图，认为不能屡次发动战役，不能无限制地扩张权威，因而下诏让公卿大夫、贤良、文学讨论，提出纠正弯曲、从细微处复兴汉家的路径。你们身为汉家公卿，应该思考百姓之所急，匈奴之所害，根据圣明君主的心意，确定安乐太平的大业。可是现在你们却仍然留心于伐胡的下策，摧败与民休息的根本大计，不顺从皇上心意，不能说你们对皇上尽了忠心。”</p><p>大夫曰：“初，贰师不克宛而还也[(1)]，议者欲使人主不遂忿[(2)]，则西域皆瓦解而附于胡[(3)]，胡得众国而益强。先帝绝奇听[(4)]，行武威[(5)]，还袭宛[(6)]，宛举国以降，效其器物，致其宝马。乌孙之属骇胆[(7)]，请为臣妾。匈奴失魄，奔走遁逃，虽未尽服，远处寒苦硗埆之地[(8)]，壮者死于祁连、天山，其孤未复。故群臣议以为匈奴困于汉兵，折翅伤翼，可遂击服[(9)]。会先帝弃群臣[(10)]，以故匈奴不革[(11)]。譬如为山[(12)]，未成一篑而止[(13)]，度功业而无继成之理[(14)]，是弃与胡而资强敌也[(15)]。辍几沮成[(16)]，为主计若斯[(17)]，亦未可谓尽忠也。”</p><p>【注释】</p><p>[(1)]贰师不克宛而还：《史记·大宛列传》载：“贰师将军军既西过盐水，当道小国恐，各坚城守，不肯给食。攻之不能下。下者得食，不下者数日则去。比至郁成，士至者不过数千，皆饥罢。攻郁成，郁成大破之，所杀伤甚众。贰师将军与哆、始成等计：‘至郁成尚不能举，况至其王都乎？’引兵而还。往来二岁。还至燉煌，士不过十一二。”贰师，贰师将军李广利。</p><p>[(2)]欲使：原作“故使”，据张敦仁说校改。遂忿：发泄忿恨。</p><p>[(3)]则西域皆瓦解而附于胡：议者不希望李广利伐宛事件重演，以免西域有心归附汉家的各国意志瓦解，转而依附匈奴。《史记·大宛列传》载：“公卿及议者皆愿罢击宛军，专力攻胡。”</p><p>[(4)]绝奇听：拒绝听从这些奇谈怪论。</p><p>[(5)]行武威：施行军事威力。</p><p>[(6)]还袭宛：《史记·大宛列传》载：“天子业已诛宛，宛小国而不能下，则大夏之属轻汉，而宛善马绝不来，乌孙、仑头易苦汉使矣，为外国笑。乃案言伐宛尤不便者邓光等，赦囚徒材官，益发恶少年及边骑，岁余而出燉煌者六万人，负私从者不与。”</p><p>[(7)]乌孙：西域古国。乌孙人最初在敦煌、祁连一带游牧，后迁至伊犁河流域。骇胆：吓破了胆。</p><p>[(8)]硗埆（qiāo què）：土地贫瘠。</p><p>[(9)]遂：成功。</p><p>[(10)]会：恰逢。先帝弃群臣：汉武帝死于公元前87年。</p><p>[(11)]不革：没有变化。</p><p>[(12)]为山：堆土成山。《论语·子罕》：“譬如为山，未成一篑，止，吾止也。”</p><p>[(13)]篑（kuì）：盛土的竹筐。</p><p>[(14)]度：揣度，引申为谋划。继：原作“断”，据杨沂孙说校改。</p><p>[(15)]资：资助，帮助。</p><p>[(16)]辍：中止。几：接近成功的事。沮：破坏。成：成功。</p><p>[(17)]若斯：如此。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“当初，贰师将军李广利未能战胜大宛而退还敦煌，朝廷议政的公卿想让皇上不要为发泄忿恨而继续伐宛，认为这样会使有心归汉的西域各国意志瓦解，转而依附匈奴，而匈奴得到西域各国支持之后会变得更加强大。已故武帝拒绝听从这些奇谈怪论，决定施展军事威力，回过头来继续攻袭大宛，大宛举国投降，献上贵器宝物，奉上汗血宝马。乌孙等西域各国闻风丧胆，请求为汉天子臣妾。匈奴失魂落魄，四散奔逃隐藏，虽然未能完全臣服汉家，但他们都住在寒苦贫瘠之地，青壮年都战死在祁连山或天山，他们的孤儿还没有长大。因此群臣经过讨论后以为，匈奴困于汉兵，翅膀折伤，可以成功地将其彻底征服。恰逢武帝弃群臣而去，因而匈奴方面的战事没有什么变化。譬如堆土成山，只差一筐土就停止了，谋划伐胡功业，没有继续将其推向成功的理念，这是将功业丢弃给匈奴而去帮助强敌。中止接近成功的事业，败坏事业的成功，为君主作如此谋划，这也不能说是对皇上尽忠。”</p><p>文学曰：“有司言外国之事，议者皆徼一时之权[(1)]，不虑其后。张骞言大宛之天马汗血[(2)]，安息之真玉大鸟[(3)]，县官既闻如甘心焉[(4)]，乃大兴师伐宛，历数期而后克之[(5)]。夫万里而攻人之国，兵未战而物故过半[(6)]，虽破宛得宝马，非计也。当此之时，将卒方赤面而事四夷[(7)]，师旅相望，郡国并发，黎人困苦[(8)]，奸伪萌生，盗贼并起，守尉不能禁，城邑不能止。然后遣上大夫衣绣衣以兴击之[(9)]。当此时，百姓元元，莫必其命[(10)]，故山东豪杰[(11)]，颇有异心[(12)]。赖先帝圣灵斐然[(13)]。其咎皆在于欲毕匈奴而远几也[(14)]。为主计若此，可谓忠乎？”</p><p>【注释】</p><p>[(1)]徼（jiào）：求。原作“激”，据张敦仁说校改。权：权宜之计。《史记·匈奴列传》：“世俗之言匈奴者，患其徼一时之权。”</p><p>[(2)]张骞言大宛之天马汗血：《史记·大宛列传》载张謇对汉武帝说：“大宛在匈奴西南，在汉正西，去汉可万里。其俗土著，耕田，田稻麦。有蒲陶酒。多善马，马汗血，其先天马子也。”</p><p>[(3)]安息：西方作“帕提亚（Parthia）”，伊朗高原古代国家，中国史籍称“安息”。《史记·大宛列传》载张謇对汉武帝说：“条枝在安息西数千里，临西海。暑湿。耕田，田稻。有大鸟，卵如甕。”真玉：未闻。大鸟：驼鸟。</p><p>[(4)]如：而。甘心：快意。原作“甘水”，据杨沂孙、张敦仁说校改。</p><p>[(5)]数期：数年。</p><p>[(6)]物故：指死亡。一说，“物”当作“歾”，意为终。</p><p>[(7)]赤面：红脸，形容将士与敌厮杀时血脉贲张的面容。事：讨伐。</p><p>[(8)]黎人：黎民。</p><p>[(9)]衣绣衣：穿着绣花衣，这是汉朝派去镇压农民起义的使者的服饰。兴击：以军兴之法去攻击。</p><p>[(10)]必其命：保障生命。必，判定。</p><p>[(11)]山东豪杰：指农民起义军。</p><p>[(12)]异心：反叛之心。</p><p>[(13)]斐然：有文采的样子，引申为有威望的样子。</p><p>[(14)]毕匈奴：完成征服匈奴大业。远几：远离庶几可以休战的大计。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“主管官员谈论外国之事，议论者都追求一时的权宜之计，不考虑它的后果。张骞对武帝说，大宛国的天马流汗殷红如血，安息国的真玉鸵鸟，朝廷听说之后，便想得到这些异物以快心意，于是大举兴师，征伐大宛，经历几年之后才战胜大宛。途经万里之遥而去攻打他人之国，士兵尚未交战就已死亡过半，虽然攻破大宛得到宝马，但这绝非国之良计。在那个时候，中国将士正在艰苦地征伐四夷，道路上到处都是军队，各郡与封国同时征发，黎民百姓困苦不堪，奸诈之徒开始出现，盗贼四处兴起，郡守与县尉不能禁止，城郭村落无法阻挡。此后朝廷派遣上大夫穿着特使的绣花衣，用军兴之法去讨伐。在那个时候，老百姓没有人能够保障自己的生命，因此山东起义军都有反叛之心。幸赖已故武帝在天圣灵的威力才转乱为治。这其中的过错，都在于主管官员一心想完成征服匈奴大业，不考虑庶几可以休战的大计。像这样为君主谋划，能够称得上忠诚吗？”</p>',94)])])}const g=t(i,[["render",n]]);export{f as __pageData,g as default};
